package com.lauzhack.twin.interview

import com.lauzhack.twin.model.Employment
import com.lauzhack.twin.model.Household
import com.lauzhack.twin.model.InterviewQuestion
import com.lauzhack.twin.model.FinancialStatement
import com.lauzhack.twin.model.Preferences
import kotlinx.serialization.Serializable

// Root of content/interview.json, generated by tools/interview.py from the dataset. The JSON also carries the ES/EN
// texts (`text`, `label`) used to write the UI strings; the app reads them from the strings through textKey / labelKey,
// so decode with ignoreUnknownKeys = true.
@Serializable
data class InterviewCatalog(
    val version: Int,
    val questions: List<InterviewQuestion>,
)

// Root of content/interview-defaults.json: medians of the dataset for the answers "I don't know" (an option that sets no
// field) and to size the goal. Every value says how many people of the dataset are behind it (n).
@Serializable
data class InterviewDefaults(
    val version: Int,
    val limits: InterviewLimits,
    val ageBands: List<AgeBand>,
    val incomeByEmployment: Map<Employment, Median>,    // NOT_WORKING = the dataset's students (the only non-working group)
    val incomeOverall: Median,
    val rentByCityHousehold: Map<String, Median>,       // "Lausanne|SINGLE"
    val rentByCity: Map<String, Median>,
    val rentByHousehold: Map<Household, Median>,
    val rentOverall: Median,
    val cashByAgeBand: List<Median>,                    // same order as ageBands
    val cashOverall: Median,
    val goals: Map<String, GoalDefault>,                // dataset goal_name -> typical size, date and priority
    val monthlyOutflowChf: Double,                      // median monthly expenses in the ledger (anchor of the cushion options)
)

@Serializable
data class InterviewLimits(
    val goalTargetChf: List<Double>,                    // [smallest, largest] goal of the dataset
)

@Serializable
data class AgeBand(val from: Int, val to: Int? = null)  // from <= age < to (open end: null)

@Serializable
data class Median(val chf: Double, val n: Int)

@Serializable
data class GoalDefault(
    val incomeRatio: Double,                            // target = incomeRatio x monthly income (dataset median)
    val targetDate: String,
    val priority: String,                               // "HIGH" | "MEDIUM"
    val n: Int,
)

// Root of content/alexia.json: the demo profile (the challenge's Alexia, her opening statement in the dataset).
@Serializable
data class DemoProfile(
    val statement: FinancialStatement,
    val preferences: Preferences,
)
